mapper.select:
select ep.id, ep.experiment_code, ep.experiment_name, ep.experiment_title, ep.experiment_field, ep.research_hypothesis, ep.experiment_desc, ep.experiment_remark, ep.experiment_contact, ep.contact_phone, ep.contact_email, ep.ethics_audit, ep.experiment_tag, ep.experiment_scene, ep.groups_number, ep.experiment_person_number, ep.experiment_status, ep.intelligent_model, ep.protocol, ep.experiment_attribution, ep.holding_status, ep.creator, ep.create_date, ep.updater, ep.update_date, ep.update_name, su.real_name as create_name, ep.start_time, ep.end_time, ep.publish_time, ep.is_deleted, ep.experiment_style, case when epf.id is not null then 1 else 0 end as is_favorite from t_experiment_plan ep left join sys_user su on ep.creator = su.id and su.is_deleted = 0 left join t_favorite epf on ep.id = epf.target_id and epf.favorite_type = 'EXPERIMENT_PLAN' and epf.user_id = #{userId} and epf.is_deleted = 0 where ep.is_deleted = 0 and ep.holding_status = 'PUBLIC'
and ep.experiment_status = #{dto.experimentStatus}
and ep.experiment_code like concat('%', #{dto.experimentCode}, '%')
and ep.experiment_scene like concat('%', #{dto.experimentScene}, '%')
and ep.experiment_contact like concat('%', #{dto.experimentContact}, '%')
and ep.experiment_name like concat('%', #{dto.experimentName}, '%')
and ep.experiment_field like concat('%', #{dto.experimentField}, '%')
and ep.experiment_attribution = #{dto.experimentAttribution}
and ep.publish_time >= #{dto.publishTimeStart}
and ep.publish_time <= #{dto.publishTimeEnd}
order by ep.update_date desc, ep.id desc
